// Registers PeaklyWidgetBridge with Capacitor.
//
// WHY THIS EXISTS — verified against @capacitor/ios 6.2.1 source
// (CapacitorBridge.swift:287 `registerPlugins`):
//
//   Capacitor does NOT scan the ObjC runtime for CAPPlugin subclasses. It reads
//   `capacitor.config.json` from the app bundle and registers ONLY the class
//   names listed in `packageClassList`. That list is generated by `npx cap sync`
//   from the Capacitor packages found in node_modules.
//
//   Our bridge lives in the app target, not an npm package, so cap sync never
//   lists it — and the plugin is invisible to JS no matter how correct the Swift
//   is (right @objc name, CAPBridgedPlugin conformance, compiled into the target,
//   all of it). There is no error; window.Capacitor.Plugins simply lacks it.
//
// So: after every `npx cap sync ios`, append our class to that list.
// Idempotent — safe to run repeatedly.
//
//   node scripts/register-widget-plugin.mjs

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const CONFIG = path.join(ROOT, "ios/App/App/capacitor.config.json");
const CLASS_NAME = "PeaklyWidgetBridge";   // must match @objc(...) in the Swift

if (!fs.existsSync(CONFIG)) {
  console.error(`Not found: ${CONFIG}\nRun \`npx cap sync ios\` first.`);
  process.exit(1);
}

const cfg = JSON.parse(fs.readFileSync(CONFIG, "utf8"));
cfg.packageClassList = cfg.packageClassList || [];

if (cfg.packageClassList.includes(CLASS_NAME)) {
  console.log(`✓ ${CLASS_NAME} already registered — nothing to do.`);
  console.log(`  packageClassList: ${cfg.packageClassList.join(", ")}`);
  process.exit(0);
}

cfg.packageClassList.push(CLASS_NAME);
fs.writeFileSync(CONFIG, JSON.stringify(cfg, null, 2) + "\n");

const check = JSON.parse(fs.readFileSync(CONFIG, "utf8"));
if (!check.packageClassList.includes(CLASS_NAME)) {
  console.error("✗ write failed — class not present after save");
  process.exit(1);
}
console.log(`✓ registered ${CLASS_NAME} with Capacitor`);
console.log(`  packageClassList: ${check.packageClassList.join(", ")}`);
console.log(`\nRebuild in Xcode (⇧⌘K then ⌘R). The plugin will now appear in`);
console.log(`window.Capacitor.Plugins and the widget will receive data.`);
